#include <vector>
#include <iostream>
#include <algorithm>
#include <cstdio>
using namespace std;

int N, V, E;
int mat[301][301];
int A[301], B[301], initialA[301];

void emit(int from, int to, int amount, bool output, long long& count) {
    ++count;
    if (output) {
        printf("%d %d %d\n", from + 1, to + 1, amount);
    }
}

void flow2(const vector<int>& path, int pos, int d,
           bool output, long long& count) {
    if (pos + 1 == static_cast<int>(path.size())) return;

    int u = path[pos];
    int v = path[pos + 1];

    if (A[v] + d <= V) {
        A[u] -= d;
        A[v] += d;
        emit(u, v, d, output, count);
        flow2(path, pos + 1, d, output, count);
    } else {
        int first = V - A[v];

        A[u] -= first;
        A[v] += first;
        if (first > 0) emit(u, v, first, output, count);

        flow2(path, pos + 1, d, output, count);

        int remaining = d - first;
        A[u] -= remaining;
        A[v] += remaining;
        emit(u, v, remaining, output, count);
    }
}

void flow(int s, int t, int d, bool output, long long& count) {
    vector<int> path;
    path.reserve(N);
    path.push_back(s);

    int current = s;
    while (current != t) {
        int next = -1;
        for (int y = 0; y < N; ++y) {
            if (mat[current][y] == 1 &&
                mat[y][t] == mat[current][t] - 1) {
                next = y;
                break;
            }
        }
        if (next == -1) return;
        path.push_back(next);
        current = next;
    }

    flow2(path, 0, d, output, count);
}

bool run(bool output, long long& count) {
    count = 0;

    for (int x = 0; x < N; ++x) {
        for (int y = 0; y < N; ++y) {
            if (mat[x][y] > N) continue;

            int d = min(A[x] - B[x], B[y] - A[y]);
            if (d <= 0) continue;

            flow(x, y, d, output, count);
        }
    }

    for (int i = 0; i < N; ++i) {
        if (A[i] != B[i]) return false;
    }
    return true;
}

void solve() {
    cin >> N >> V >> E;

    for (int i = 0; i < N; ++i) {
        cin >> A[i];
        initialA[i] = A[i];
    }
    for (int i = 0; i < N; ++i) cin >> B[i];

    for (int x = 0; x < N; ++x) {
        for (int y = 0; y < N; ++y) {
            mat[x][y] = 9999;
        }
        mat[x][x] = 0;
    }

    for (int i = 0; i < E; ++i) {
        int x, y;
        cin >> x >> y;
        --x;
        --y;
        mat[x][y] = mat[y][x] = 1;
    }

    for (int k = 0; k < N; ++k) {
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                mat[i][j] = min(mat[i][j], mat[i][k] + mat[k][j]);
            }
        }
    }

    long long count;
    if (!run(false, count)) {
        printf("NO\n");
        return;
    }

    printf("%lld\n", count);

    for (int i = 0; i < N; ++i) A[i] = initialA[i];

    long long ignored;
    run(true, ignored);
}

int main() {
    solve();
    return 0;
}

#include <vector>
