using namespace std;

int N, V, E;
int mat[301][301];
int A[301], B[301];
vector<pair<pair<int, int>, int>> R;

void flow2(vector<int>& P, int si, int ti, int d) {
	if (si == ti) return;

	if (A[P[si + 1]] + d <= V) {
		A[P[si]] -= d;
		A[P[si + 1]] += d;
		R.push_back({{P[si], P[si + 1]}, d});
		flow2(P, si + 1, ti, d);
	} else {
		int d2 = V - A[P[si + 1]];
		A[P[si]] -= d2;
		A[P[si + 1]] += d2;

		if (d2 > 0)
			R.push_back({{P[si], P[si + 1]}, d2});

		flow2(P, si + 1, ti, d);

		A[P[si]] -= d - d2;
		A[P[si + 1]] += d - d2;
		R.push_back({{P[si], P[si + 1]}, d - d2});
	}
}

#define FOR(y, N) for (int y = 0; y < (N); ++y)

void flow(int s, int t, int d) {
	vector<int> P;
	P.push_back(s);

	for (int current = s; current != t;) {
		int next = -1;
		for (int y = 0; y < N; ++y) {
			if (mat[current][y] == 1 &&
			    mat[y][t] == mat[current][t] - 1) {
				next = y;
				break;
			}
		}
		if (next == -1) return;
		P.push_back(next);
		current = next;
	}

	flow2(P, 0, static_cast<int>(P.size()) - 1, d);
}

