	FOR(x, N) mat[x][x] = 0;

	FOR(i, E) {
		int x, y;
		cin >> x >> y;
		mat[x - 1][y - 1] = 1;
		mat[y - 1][x - 1] = 1;
	}

	FOR(k, N)
		FOR(i, N)
			FOR(j, N)
				mat[i][j] = min(mat[i][j], mat[i][k] + mat[k][j]);

	FOR(x, N) {
		FOR(y, N) {
			if (mat[x][y] > N) continue;

			int d = min(A[x] - B[x], B[y] - A[y]);
			if (d <= 0) continue;

			flow(x, y, d);
